<?php /** Optional Phase 4 gallery preview; empty tenants render no filler content. */ ?>
<?php if($albums!==[]): ?><section class="section"><div class="container"><div class="section-heading"><h2>Gallery</h2><a class="text-link" href="<?= esc(public_site_url('gallery')) ?>">View gallery →</a></div><div class="card-grid"><?php foreach($albums as $album): ?><a class="gallery-preview" href="<?= esc(public_site_url('gallery_album',[$album['slug']])) ?>"><img src="<?= esc(public_site_path('media/'.$album['cover_media_id'].'/medium')) ?>" srcset="<?= esc(public_site_path('media/'.$album['cover_media_id'].'/thumbnail')) ?> 480w, <?= esc(public_site_path('media/'.$album['cover_media_id'].'/medium')) ?> 960w, <?= esc(public_site_path('media/'.$album['cover_media_id'].'/large')) ?> 1600w" sizes="(max-width: 42rem) 100vw, 33vw" loading="lazy" alt="<?= esc($album['title']) ?>"><strong><?= esc($album['title']) ?></strong></a><?php endforeach ?></div></div></section><?php endif ?>
